public class Main {
    public static void main(String[] args) {
        int[] scores = {72, 85, 90, 64, 78, 95};

        System.out.println("First: " + scores[0]);
        System.out.println("Third: " + scores[2]);
        System.out.println("Last: " + scores[scores.length - 1]);

        scores[1] += 5;
        System.out.println("Second is now: " + scores[1]);
    }
}

