import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        double[] prices = {2.5, 4.0, 3.75};

        double[] alias = prices;
        alias[1] = 4.5;

        double[] copy = prices.clone();
        copy[2] = 5.25;

        System.out.println("prices: " + Arrays.toString(prices));
        System.out.println("alias: " + Arrays.toString(alias));
        System.out.println("copy: " + Arrays.toString(copy));
        System.out.println("alias == prices: " + (alias == prices));
        System.out.println("copy == prices: " + (copy == prices));

        prices = Arrays.copyOf(prices, prices.length + 2);
        System.out.println("grown: " + Arrays.toString(prices));
        System.out.println("alias length: " + alias.length);
    }
}
